//! Copies the places table generated by Nix into `OUT_DIR`.
//!
//! The places are declared in `assets/world.nix` and generated by
//! `nix/scripts/gen-world.py`, which is also what refuses a zone
//! `zone1970.tab` does not know. This build script does NOT generate them —
//! generating here would reimplement Nix logic (invariant 5) and would lose
//! the one refusal that matters. Same shape as `ronoctua-tokens/build.rs`.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_WORLD_RS");

    let generated = env::var("RONOCTUA_WORLD_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_WORLD_RS is not set.\n\
             \n\
             The glance's places are generated by Nix out of assets/world.nix.\n\
             Enter the environment with `direnv allow` (or `nix develop`), which\n\
             sets the variable, or build through the flake with `nix build`."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("world.rs");
    // DELETE FIRST — the store file is read-only. See `ronoctua-tokens/build.rs`.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
